# Read-only frozen-result audit. No generated observations, model fitting or jobs.
stopifnot(as.character(getRversion())=='4.5.2')
f<-grep('^--file=',commandArgs(),value=TRUE)[1];C<-dirname(dirname(normalizePath(sub('^--file=','',f))));R<-dirname(dirname(C));P<-dirname(R)
archive<-Sys.getenv('TSR_TIER1_ARCHIVE')
sha<-function(p)strsplit(system2('shasum',c('-a','256',shQuote(p)),stdout=TRUE),'[[:space:]]+')[[1]][1]
inv<-read.csv(file.path(C,'evidence/source_inventory.csv'));for(i in seq_len(nrow(inv)))stopifnot(sha(if(nzchar(inv$project_relative[i]))file.path(P,inv$project_relative[i]) else archive)==inv$sha256[i])
bind<-function(x)if(length(x))do.call(rbind,x) else data.frame()
wr<-function(x,n,w='tables')write.csv(x,file.path(C,w,n),row.names=FALSE,na='NA')
ci<-function(v,binary=FALSE){v<-v[is.finite(v)];n<-length(v);if(!n)return(c(n_finite=0,events=NA,mean=NA,mcse=NA,lower=NA,upper=NA));se<-sd(v)/sqrt(n);lim<-mean(v)+c(-1,1)*qt(.975,n-1)*se;if(binary){stopifnot(all(v%in%0:1));lim<-binom.test(sum(v),n)$conf.int};c(n_finite=n,events=if(binary)sum(v) else NA,mean=mean(v),mcse=se,lower=lim[1],upper=lim[2])}
pairci<-function(a,b,binary=FALSE){ok<-is.finite(a)&is.finite(b);a<-a[ok];b<-b[ok];n<-length(a);z<-ci(a-b);up<-down<-NA;if(binary&&n){up<-sum(a==1&b==0);down<-sum(a==0&b==1);u<-binom.test(up,n,conf.level=.975)$conf.int;d<-binom.test(down,n,conf.level=.975)$conf.int;z[c('lower','upper')]<-c(u[1]-d[2],u[2]-d[1])};c(z,n_up=up,n_down=down)}
metrics<-c('MajorARI','MinorityClusterF1','MinorityDetectionF1_all_extra_v2','AnyMicroDiscovery','any_native_micro','SpuriousExtraClusters','MacroFalsePositiveReassignment','FalseExtraAssignmentRate','NoiseRecall','n_accepted_micro','residual_assignment_rate','end_to_end_seconds','micro_seconds','macro_seconds','global_p','entered_mc','AnySpuriousExtra')
binary<-c('AnyMicroDiscovery','any_native_micro','entered_mc','AnySpuriousExtra')
main<-function(){
 tmp<-tempfile('r2c4_archive_');dir.create(tmp);on.exit(unlink(tmp,recursive=TRUE));untar(archive,files='replications.csv',exdir=tmp);all<-read.csv(file.path(tmp,'replications.csv'))
 design<-read.csv(file.path(P,'revision_scientific_reports/config/design.csv'));design<-design[design$tier==1,];tasks<-read.csv(file.path(P,'revision_scientific_reports/config/tasks_tier1.csv'))
 stopifnot(nrow(all)==98800,all(all$status=='OK'),length(unique(all$cell_id))==282,nrow(tasks)==9880,!anyDuplicated(all[c('cell_id','replication')]))
 k<-paste(all$cell_id,all$replication);tk<-unlist(lapply(seq_len(nrow(tasks)),function(i)paste(tasks$cell_id[i],seq.int(tasks$rep_start[i],tasks$rep_end[i]))));stopifnot(!anyDuplicated(tk),setequal(k,tk))
 idx<-match(all$cell_id,design$cell_id);for(nm in intersect(names(all),names(design)))stopifnot(identical(is.na(all[[nm]]),is.na(design[[nm]][idx])),all(as.character(all[[nm]])==as.character(design[[nm]][idx]),na.rm=TRUE))
 env<-new.env();sys.source(file.path(P,'revision_scientific_reports/R/common.R'),env)
 for(s in c('data','algorithm','null')){stream<-match(s,c('data','algorithm','null'))-1L;rp<-if(s=='data')rep(1L,nrow(all)) else all[[paste0(s,'_repeat')]];stopifnot(all(all[[paste0(s,'_seed')]]==mapply(env$seed_id,all$dataset_id,all$replication,rp,MoreArgs=list(stream=stream))))}
 all$minPts<-pmax(5,all$p*all$minpts_multiplier);all$entered_mc<-as.integer(all$rejection_reason%in%c('accepted','global_p','candidate_max'));all$AnySpuriousExtra<-as.integer(all$SpuriousExtraClusters>0)
 z<-all[all$method=='TSRClust'&all$experiment%in%c('B','C'),];stopifnot(nrow(z)==31600,length(unique(z$cell_id))==158,nrow(unique(z[c('dataset_id','replication','data_seed')]))==1800)
 stopifnot(all(z$n_residual>=z$minPts),all(z$any_native_micro==as.integer(z$n_accepted_micro>0)))
 meta<-c('cell_id','experiment','scenario','reference','density','minpts_multiplier','minPts','novelty','B','p','q','n','dataset_id','minority_ratio','minority_proximity','noise_type','rule','requested_alpha')
 cells<-reasons<-list();for(cid in unique(z$cell_id)){a<-z[z$cell_id==cid,];m<-a[1,meta];rownames(m)<-NULL;stopifnot(nrow(a)==200);for(v in metrics)cells[[length(cells)+1]]<-cbind(m,n_records=nrow(a),metric=v,as.data.frame(as.list(ci(a[[v]],v%in%binary))));for(why in unique(a$rejection_reason))reasons[[length(reasons)+1]]<-cbind(m,reason=why,n_records=nrow(a),count=sum(a$rejection_reason==why))}
 cells<-bind(cells);wr(cells,'cell_summaries.csv');wr(bind(reasons),'rejection_reasons.csv');wr(z[!duplicated(z$cell_id),intersect(names(design),names(z))],'target_design.csv')
 wr(all[!duplicated(all$cell_id),names(design)],'experiment_inventory.csv')
 fields<-c(setdiff(names(design),c('cell_id','scenario','experiment','reps')), 'replication','data_seed','algorithm_seed','null_seed','algorithm_version','metric_version','n_residual','macro_objective','macro_code','estimated_K')
 proof<-changes<-pairs<-list();counter<-0L
 compare<-function(a,b,family,vary){a<-a[order(a$replication),];b<-b[order(b$replication),];stopifnot(nrow(a)==200,nrow(b)==200,identical(a$replication,b$replication));for(v in setdiff(fields,vary))stopifnot(identical(a[[v]],b[[v]]));counter<<-counter+1L
  row<-data.frame(contrast_id=counter,family=family,scenario=a$scenario[1],new_cell=a$cell_id[1],baseline_cell=b$cell_id[1],new_reference=a$reference[1],baseline_reference=b$reference[1],new_density=a$density[1],baseline_density=b$density[1],new_minPts=a$minPts[1],baseline_minPts=b$minPts[1],new_novelty=a$novelty[1],baseline_novelty=b$novelty[1],new_B=a$B[1],baseline_B=b$B[1])
  proof[[length(proof)+1]]<<-cbind(row,n_pairs=200,all_noncontrast_fields_equal=TRUE,three_starting_seeds_equal=TRUE,macro_objective_code_residual_K_equal=TRUE,raw_matrix_hashes_exported=FALSE)
  changes[[length(changes)+1]]<<-cbind(row,n_pairs=200,entered_mc_up=sum(a$entered_mc==1&b$entered_mc==0),entered_mc_down=sum(a$entered_mc==0&b$entered_mc==1),native_up=sum(a$any_native_micro==1&b$any_native_micro==0),native_down=sum(a$any_native_micro==0&b$any_native_micro==1))
  bind(lapply(metrics,function(v)cbind(row,metric=v,mean_new=if(any(is.finite(a[[v]])))mean(a[[v]],na.rm=TRUE) else NA_real_,mean_baseline=if(any(is.finite(b[[v]])))mean(b[[v]],na.rm=TRUE) else NA_real_,as.data.frame(as.list(pairci(a[[v]],b[[v]],v%in%binary))))))}
 groups<-unique(z[c('experiment','scenario','reference')]);for(i in seq_len(nrow(groups))){g<-groups[i,];a<-z[z$experiment==g$experiment&z$scenario==g$scenario&z$reference==g$reference&z$density==2&z$minpts_multiplier==2&z$B==49,];for(v in c(.95,.975,.99,.999))pairs[[length(pairs)+1]]<-compare(a[a$novelty==v,],a[a$novelty==.995,],'novelty','novelty')}
 for(sc in unique(z$scenario[z$experiment=='B']))for(nv in sort(unique(z$novelty))){a<-z[z$experiment=='B'&z$scenario==sc&z$novelty==nv,];for(rr in list(c('tclust_direct','legacy_empirical'),c('regularized_mcd','legacy_empirical'),c('regularized_mcd','tclust_direct')))pairs[[length(pairs)+1]]<-compare(a[a$reference==rr[1],],a[a$reference==rr[2],],'reference','reference')}
 for(sc in unique(z$scenario[z$experiment=='C'])){
  a<-z[z$experiment=='C'&z$scenario==sc&z$novelty==.995,];base<-a[a$density==2&a$minpts_multiplier==2&a$B==49,]
  for(v in c(1.5,2.5,3))pairs[[length(pairs)+1]]<-compare(a[a$density==v&a$minpts_multiplier==2&a$B==49,],base,'density','density')
  for(v in c(1,3,4))pairs[[length(pairs)+1]]<-compare(a[a$density==2&a$minpts_multiplier==v&a$B==49,],base,'minpts','minpts_multiplier')
  for(v in c(99,199))pairs[[length(pairs)+1]]<-compare(a[a$density==2&a$minpts_multiplier==2&a$B==v,],base,'B','B')
  for(mp in c(1,4))pairs[[length(pairs)+1]]<-compare(a[a$density==3&a$minpts_multiplier==mp&a$B==49,],a[a$density==1.5&a$minpts_multiplier==mp&a$B==49,],'interaction_density','density')
  for(de in c(1.5,3))pairs[[length(pairs)+1]]<-compare(a[a$density==de&a$minpts_multiplier==4&a$B==49,],a[a$density==de&a$minpts_multiplier==1&a$B==49,],'interaction_minpts','minpts_multiplier')
 }
 pairs<-bind(pairs);stopifnot(counter==226);wr(pairs,'paired_sensitivity.csv');wr(bind(proof),'pairing_proofs.csv','evidence');wr(bind(changes),'decision_changes.csv')
 # Actual four-corner interactions on the same 200 datasets, not new fits.
 did<-dproof<-list();for(sc in unique(z$scenario[z$experiment=='C'])){
  a<-z[z$experiment=='C'&z$scenario==sc&z$novelty==.995&z$B==49,]
  corner<-function(de,mp){b<-a[a$density==de&a$minpts_multiplier==mp,];b[order(b$replication),]}
  arms<-list(corner(3,4),corner(1.5,4),corner(3,1),corner(1.5,1));stopifnot(all(lengths(lapply(arms,`[[`,'replication'))==200))
  for(b in arms)for(v in setdiff(fields,c('density','minpts_multiplier')))stopifnot(identical(b[[v]],arms[[1]][[v]]))
  row<-data.frame(scenario=sc,high_density_high_support=arms[[1]]$cell_id[1],low_density_high_support=arms[[2]]$cell_id[1],high_density_low_support=arms[[3]]$cell_id[1],low_density_low_support=arms[[4]]$cell_id[1],n_pairs=200)
  dproof[[length(dproof)+1]]<-cbind(row,DGP_seeds_StageI_and_fixed_settings_equal=TRUE)
  for(v in metrics){vec<-lapply(arms,`[[`,v);ok<-Reduce(`&`,lapply(vec,is.finite));vec<-lapply(vec,function(b)b[ok]);score<-vec[[1]]-vec[[2]]-vec[[3]]+vec[[4]];stat<-ci(score)
   if(v%in%binary&&length(score)){lim<-lapply(vec,function(b)binom.test(sum(b),length(b),conf.level=.9875)$conf.int);stat[c('lower','upper')]<-c(lim[[1]][1]-lim[[2]][2]-lim[[3]][2]+lim[[4]][1],lim[[1]][2]-lim[[2]][1]-lim[[3]][1]+lim[[4]][2])}
   did[[length(did)+1]]<-cbind(row,metric=v,as.data.frame(as.list(stat)),interval=if(v%in%binary)'Conservative pointwise95%;four98.75% CP margins;within-dataset dependence allowed' else 'Pointwise paired t Monte Carlo95% on signed within-dataset interaction',direction='(density3-1.5 at support4p) minus (density3-1.5 at supportp)')
  }
 };wr(bind(did),'density_minpts_interactions.csv');wr(bind(dproof),'interaction_pairing.csv','evidence')
 # Exact reproduction of all previously approved overlapping sensitivity rows.
 reconcile<-list();checkcells<-function(path){old<-read.csv(path);for(i in seq_len(nrow(old))){a<-cells[cells$cell_id==old$cell_id[i]&cells$metric==old$metric[i],];stopifnot(nrow(a)==1,a$n_finite==old$n_finite[i]);for(nm in c('mean','mcse','lower','upper')){oldnm<-if(nm%in%names(old))nm else switch(nm,lower='lo',upper='hi');stopifnot(isTRUE(all.equal(a[[nm]],old[[oldnm]][i],tolerance=1e-11)))}};data.frame(source=path,kind='cell',n_rows=nrow(old),status='PASS')}
 checkpairs<-function(path){old<-read.csv(path);for(i in seq_len(nrow(old))){nc<-if('new_cell'%in%names(old))old$new_cell[i] else old$alternative_cell[i];a<-pairs[pairs$new_cell==nc&pairs$baseline_cell==old$baseline_cell[i]&pairs$metric==old$metric[i],];stopifnot(nrow(a)==1,a$n_finite==old$n_finite[i]);for(nm in c('mean','mcse','lower','upper')){oldnm<-if(nm%in%names(old))nm else switch(nm,lower='lo',upper='hi');stopifnot(isTRUE(all.equal(a[[nm]],old[[oldnm]][i],tolerance=1e-11)))}};data.frame(source=path,kind='paired',n_rows=nrow(old),status='PASS')}
 for(path in c('reviewer1/comment2/tables/sensitivity_cell_performance.csv','reviewer1/comment5/tables/minpts_cell_performance.csv','reviewer2/comment3/tables/cell_summaries.csv'))reconcile[[length(reconcile)+1]]<-checkcells(file.path(R,path))
 for(path in c('reviewer1/comment2/tables/paired_novelty_differences.csv','reviewer1/comment5/tables/minpts_paired_differences.csv','reviewer2/comment2/tables/paired_B_vs49.csv','reviewer2/comment3/tables/paired_thresholds.csv','reviewer2/comment3/tables/paired_references.csv'))reconcile[[length(reconcile)+1]]<-checkpairs(file.path(R,path))
 # Reproduce the prior complete D1/D2 paired audit directly from immutable data.
 fair<-all[all$experiment%in%c('D1-E','D2-E'),];stopifnot(nrow(fair)==5600,nrow(unique(fair[c('dataset_id','replication','data_seed')]))==400)
 sel<-fair$experiment=='D2-E';for(v in c('K_correct_macro','K_above_macro','K_below_macro','K_correct_total','K_above_total','K_at_upper_boundary'))fair[[v]]<-NA_real_
 fair$K_correct_macro[sel]<-as.integer(fair$estimated_K[sel]==fair$main_k[sel]);fair$K_above_macro[sel]<-as.integer(fair$estimated_K[sel]>fair$main_k[sel]);fair$K_below_macro[sel]<-as.integer(fair$estimated_K[sel]<fair$main_k[sel]);fair$K_correct_total[sel]<-as.integer(fair$estimated_K[sel]==fair$main_k[sel]+fair$q[sel]);fair$K_above_total[sel]<-as.integer(fair$estimated_K[sel]>fair$main_k[sel]+fair$q[sel]);fair$K_at_upper_boundary[sel]<-as.integer(fair$estimated_K[sel]==fair$kmax[sel])
 old<-read.csv(file.path(R,'reviewer1/comment4/tables/paired_performance_differences.csv'));for(i in seq_len(nrow(old))){a<-fair[fair$cell_id==old$new_cell[i],];b<-fair[fair$cell_id==old$baseline_cell[i],];a<-a[order(a$replication),];b<-b[order(b$replication),];stopifnot(identical(a$data_seed,b$data_seed),identical(a$algorithm_seed,b$algorithm_seed),identical(a$null_seed,b$null_seed));v<-old$metric[i];stat<-pairci(a[[v]],b[[v]],v%in%c(binary,'K_correct_macro','K_above_macro','K_below_macro','K_correct_total','K_above_total','K_at_upper_boundary'));for(nm in c('n_finite','mean','mcse','lower','upper'))stopifnot(isTRUE(all.equal(as.numeric(stat[nm]),old[[nm]][i],tolerance=1e-11)))}
 reconcile[[length(reconcile)+1]]<-data.frame(source='reviewer1/comment4/tables/paired_performance_differences.csv',kind='fairness paired',n_rows=nrow(old),status='PASS');wr(bind(reconcile),'prior_result_reconciliation.csv','evidence')
 # Independence, design coverage and finite-denominator audit.
 coverage<-list();for(fam in c('density','minpts','B','novelty','reference','interaction_density','interaction_minpts')){pp<-pairs[pairs$family==fam,];ids<-unique(c(pp$new_cell,pp$baseline_cell));aa<-z[z$cell_id%in%ids,];coverage[[length(coverage)+1]]<-data.frame(family=fam,cells=length(ids),fit_records=nrow(aa),pair_groups=length(unique(pp$contrast_id)),replications_per_cell=200,unique_generated_datasets=nrow(unique(aa[c('dataset_id','replication','data_seed')])),p_values=paste(sort(unique(aa$p)),collapse=';'),noise_types=paste(unique(aa$noise_type),collapse=';'),mode=paste(unique(aa$mode),collapse=';'))};wr(bind(coverage),'sensitivity_coverage.csv')
 # Four actual density by four multiplier levels are not fully crossed:11/16 per scenario.
 grid<-expand.grid(density=c(1.5,2,2.5,3),minpts_multiplier=c(1,2,3,4));fact<-list();for(sc in unique(z$scenario[z$experiment=='C'])){a<-z[z$experiment=='C'&z$scenario==sc&z$B==49&z$novelty==.995,];for(i in seq_len(nrow(grid))){b<-a[a$density==grid$density[i]&a$minpts_multiplier==grid$minpts_multiplier[i],];fact[[length(fact)+1]]<-data.frame(scenario=sc,density=grid$density[i],minpts_multiplier=grid$minpts_multiplier[i],minPts=max(5,grid$minpts_multiplier[i]*a$p[1]),executed=nrow(b)>0,n_records=nrow(b),cell_id=if(nrow(b))b$cell_id[1] else NA)}};wr(bind(fact),'factorial_coverage.csv')
 dup<-z[!duplicated(z[c('experiment','scenario','reference','density','minpts_multiplier','novelty','B')]),];wr(dup[duplicated(dup[c('dataset_id','reference','density','minpts_multiplier','novelty','B')])|duplicated(dup[c('dataset_id','reference','density','minpts_multiplier','novelty','B')],fromLast=TRUE),meta],'duplicate_scientific_cells.csv','evidence')
 # Original inputs: metadata are verified separately from arguments actually consumed.
 orig<-list();for(st in c('architecture','stress','negative_control')){a<-readRDS(file.path(P,'Scientific Reports Manuscript/analysis/v2/results/final_sim_combined',paste0(st,'_replications.rds')));for(m in unique(a$method)){b<-a[a$method==m,];good<-b$status=='OK';if(m%in%c('TSRClust_validated','TCLUST','Trimmed_kmeans','OTRIMLE_fixedK'))stopifnot(all(b$requested_k==b$main_k),all(b$requested_alpha==b$residual_total));if(m=='Oracle_TCLUST')stopifnot(all(b$fitted_k[good]==b$main_k[good]+b$q[good]),all(abs(b$fitted_alpha[good]-(b$residual_total[good]-b$minority_ratio[good]))<1e-12));if(m=='tEIGEN_BIC')stopifnot(all(b$selected_g[good]>=1),all(b$selected_g[good]<=pmin(6,b$main_k[good]+pmax(b$q[good],1)+2)));orig[[length(orig)+1]]<-data.frame(study=st,method=m,n_records=nrow(b),n_OK=sum(good),nstart_metadata=paste(sort(unique(b$nstart)),collapse=';'),B_metadata=paste(sort(unique(b$null_reps)),collapse=';'),metadata_not_universal_consumed_arguments=TRUE)}};wr(bind(orig),'original_input_checks.csv','evidence')
 # Main-table numeric inputs: each row is one actual controlled C positive comparison,
 # except novelty which uses B empirical to preserve the already reported contrast.
 mainrows<-list();for(fam in c('density','novelty','minpts','B')){aa<-if(fam=='novelty')z[z$experiment=='B'&z$scenario=='B_0.05_isolated'&z$reference=='legacy_empirical',] else z[z$experiment=='C'&z$scenario=='positive',];base<-aa[aa$density==2&aa$minpts_multiplier==2&aa$novelty==.995&aa$B==49,];alt<-switch(fam,density=aa[aa$density==1.5&aa$minpts_multiplier==2&aa$novelty==.995&aa$B==49,],novelty=aa[aa$novelty==.999,],minpts=aa[aa$density==2&aa$minpts_multiplier==1&aa$novelty==.995&aa$B==49,],B=aa[aa$density==2&aa$minpts_multiplier==2&aa$novelty==.995&aa$B==199,]);pp<-pairs[pairs$new_cell==alt$cell_id[1]&pairs$baseline_cell==base$cell_id[1],];for(v in c('MinorityClusterF1','MinorityDetectionF1_all_extra_v2','any_native_micro','AnyMicroDiscovery','MacroFalsePositiveReassignment','SpuriousExtraClusters','residual_assignment_rate','end_to_end_seconds','micro_seconds'))mainrows[[length(mainrows)+1]]<-cbind(parameter=fam,pp[pp$metric==v,])};wr(bind(mainrows),'main_table_values.csv')
 wr(data.frame(check=c('Immutable scientific input hashes','Frozen records/design/task completeness','All deterministic data/algorithm/null seeds','158 B/C cells and independent dataset accounting','226 genuinely paired sensitivity groups plus4four-corner interactions','Prior approved numerical results reproduced','Original arguments/metadata and400-dataset fairness audit','No new fitting,simulated observations,installs orjobs'),status='PASS',detail=c('235 SHA256 unchanged','98800 OK;282 configurations;9880 blocks','Every archived seed matches frozen formula','31600 records;1800 unique generated datasets;200/cell','Noncontrast fields andsaved StageI identity;no raw matrix hashes',paste(sum(bind(reconcile)$n_rows),'overlapping approved rows exact'),'1408 prior paired fairness rows andoriginal information checks exact','Only archive/RDS reading,source audit andaggregation')),'analysis_checks.csv','evidence')
 saveRDS(z,file.path(C,'evidence/audited_scalar_records.rds'));writeLines(capture.output(sessionInfo()),file.path(C,'evidence/R_session_info.txt'));cat('R2C4_READONLY_ANALYSIS_OK',nrow(cells),'cell rows;',nrow(pairs),'paired metric rows;',sum(bind(reconcile)$n_rows),'prior rows reproduced\n')
}
main()
